from __future__ import annotations

from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .enums.inventory_state import InventoryStateOrStr


class InventoryAdjustmentGroup(SdkBaseModel):
    id: Optional[str] = UNSET
    """A unique ID generated by Square for the ``InventoryAdjustmentGroup``."""

    root_adjustment_id: Optional[str] = UNSET
    """The inventory adjustment of the composed variation."""

    from_state: Optional[InventoryStateOrStr] = UNSET
    """Indicates the state of a tracked item quantity in the lifecycle of goods."""

    to_state: Optional[InventoryStateOrStr] = UNSET
    """Indicates the state of a tracked item quantity in the lifecycle of goods."""


class InventoryAdjustmentGroupDict(TypedDict):
    id: NotRequired[str]
    root_adjustment_id: NotRequired[str]
    from_state: NotRequired[InventoryStateOrStr]
    to_state: NotRequired[InventoryStateOrStr]
